<script setup lang="ts">
import {ref} from 'vue'
import {apiFetch} from '../api'
import {dismissAfterFourSeconds} from '../temporary-message'
const emit=defineEmits<{saving:[value:boolean]}>()
const busy=ref(false),error=ref(''),message=ref(''),preview=ref<any>(null),filename=ref('')
dismissAfterFourSeconds(message)
async function response(r:Response){if(!r.ok){const body=await r.json().catch(()=>({}));throw Error(body.message??'Unable to transfer school data.')}return r}
async function run(action:()=>Promise<void>){busy.value=true;emit('saving',true);error.value='';message.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'Unable to transfer data.'}finally{busy.value=false;emit('saving',false)}}
async function download(){await run(async()=>{const r=await response(await apiFetch('/api/admin/school/transfer/export'));const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='studenthub-school-data.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='School data downloaded.'})}
async function upload(event:Event){preview.value=null;const file=(event.target as HTMLInputElement).files?.[0];filename.value=file?.name??'';if(!file)return;if(file.size>6000000){error.value='Choose a ZIP file smaller than 6 MB.';return}await run(async()=>{const bytes=new Uint8Array(await file.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=32768)text+=String.fromCharCode(...bytes.subarray(i,i+32768));const r=await response(await apiFetch('/api/admin/school/transfer/preview',{method:'POST',headers:{'Content-Type':'application/json','X-StudentHub':'1'},body:JSON.stringify({package:btoa(text)})}));preview.value=await r.json()})}
async function apply(){if(!preview.value)return;await run(async()=>{const r=await response(await apiFetch('/api/admin/school/transfer/apply',{method:'POST',headers:{'Content-Type':'application/json','X-StudentHub':'1'},body:JSON.stringify({token:preview.value.token})}));message.value=(await r.json()).message;preview.value=null;filename.value=''})}
</script>
<template>
<section class="transfer" :aria-busy="busy"><p class="eyebrow">SCHOOL DATA</p><h2>Import &amp; export</h2><p>Move school records together in one ZIP containing editable CSV files.</p>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p>
<div class="cards"><article><h3>Export school data</h3><p>Includes school details, years, terms, classes, students, teachers, subjects, timetables, floors, rooms, bookings and canteen menus.</p><button :disabled="busy" @click="download">Download CSV package</button><p class="muted">Keep this file private. It contains student names and contact details.</p></article>
<article><h3>Import a CSV package</h3><ol><li>Download a package and edit its CSV files.</li><li>Keep column headers, IDs and referenced records.</li><li>Upload the ZIP, review the preview, then import.</li></ol><label>Choose ZIP package<input type="file" accept=".zip,application/zip" :disabled="busy" @change="upload"></label><p class="muted">Up to 6 MB compressed, 20 MB expanded and 20,000 records. Preview expires after 10 minutes.</p></article></div>
<p class="notice">Imports add or update matching records and keep unlisted records. Existing passwords and login access stay unchanged. New login accounts start disabled; set their passwords and enable them in Accounts.</p>
<p class="muted">This transfers school data. Administrator accounts, passwords, sessions, password requests, audit history, homework, attendance and job favourites are excluded. Use a private database backup to preserve the entire system.</p>
<section v-if="preview" class="preview"><h3>Preview · {{filename}}</h3><p>{{preview.message}}</p><div class="table-scroll"><table><thead><tr><th>Records</th><th>New</th><th>Updates</th><th>Unchanged</th></tr></thead><tbody><tr v-for="s in preview.summary" :key="s.table"><td>{{s.table.replaceAll('_',' ')}}</td><td>{{s.added}}</td><td>{{s.updated}}</td><td>{{s.unchanged}}</td></tr></tbody></table></div><div class="actions"><button :disabled="busy" @click="apply">{{busy?'Working…':'Import reviewed changes'}}</button><button class="secondary" :disabled="busy" @click="preview=null">Cancel preview</button></div></section>
<p v-if="busy" role="status">Processing school data…</p></section>
</template>
<style scoped>
.transfer{background:#fff;border:1px solid #dbe5df;border-radius:16px;padding:24px;color:#294638}.transfer h2{margin:6px 0 12px}.transfer p,.transfer li{font-size:13px;line-height:1.6}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.cards article,.preview{padding:18px;border:1px solid #dbe5df;border-radius:12px;margin:14px 0}.cards h3{margin-top:0}.muted{color:#697c71}.notice,.success,.error{padding:12px;border-radius:8px}.notice,.success{background:#edf5ef}.error{background:#faeeeb;color:#a13c2c}button{border:0;border-radius:8px;background:#38624f;color:white;padding:10px 14px;font:inherit;cursor:pointer}button:disabled{opacity:.55}input{display:block;max-width:100%;margin-top:8px}label{font-weight:600;font-size:13px}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e1e9e4}th{background:#f1f6f3}.actions{display:flex;gap:10px;margin-top:16px}.secondary{background:#e8efea;color:#38624f}@media(max-width:650px){.cards{grid-template-columns:1fr;gap:0}.transfer{padding:16px}.actions{flex-wrap:wrap}}
</style>
